## Embedded SQL Database

### Basic Operations

```xiom
use xiom.sqlite;

fn main() -> Int {
  let db = sqlite::Database::open("app.db")?;

  // Create table
  db.execute("CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE
  )")?;

  // Insert
  db.execute(
    "INSERT INTO users (name, email) VALUES (?, ?)",
    ["Alice", "alice@example.com"]
  )?;

  // Query
  let rows = db.query("SELECT id, name, email FROM users")?;
  for row in rows {
    let id: Int = row.get(0);
    let name: Str = row.get(1);
    let email: Str = row.get(2);
    io.println(id.to_str() + ": " + name + " <" + email + ">");
  }
  return 0;
}
```

### Prepared Statements

```xiom
let mut stmt = db.prepare("SELECT name FROM users WHERE id = ?")?;
stmt.bind(1, 42)?;

while stmt.step() == Row {
  let name: Str = stmt.column(0);
  io.println(name);
}
```

### Transactions

```xiom
fn transfer_money(db: &Database, from: Int, to: Int, amount: Float64) -> Result<(), Error> {
  db.execute("BEGIN TRANSACTION")?;

  let result = (|| {
    db.execute("UPDATE accounts SET balance = balance - ? WHERE id = ?", [amount, from])?;
    db.execute("UPDATE accounts SET balance = balance + ? WHERE id = ?", [amount, to])?;

    // Verify no overdraft
    let balance: Float64 = db.query_one("SELECT balance FROM accounts WHERE id = ?", [from])?;
    if balance < 0.0 {
      return Err("Insufficient funds");
    }
    Ok(())
  })();

  match result {
    Ok(()) => db.execute("COMMIT")?,
    Err(e) => {
      db.execute("ROLLBACK")?;
      return Err(e);
    },
  }
  Ok(())
}
```

### ORM-Like Patterns

```xiom
pub type User = { id: Int; name: Str; email: Str; }

impl User {
  fn find_by_id(db: &Database, id: Int) -> Option[User] {
    let row = db.query_one("SELECT id, name, email FROM users WHERE id = ?", [id])?;
    return row.map(|r| User{
      id: r.get(0),
      name: r.get(1),
      email: r.get(2),
    });
  }

  fn save(self: &User, db: &Database) -> Result<(), Error> {
    db.execute(
      "INSERT OR REPLACE INTO users (id, name, email) VALUES (?, ?, ?)",
      [self.id, &self.name, &self.email]
    )?;
    Ok(())
  }
}
```

### Migrations

```xiom
fn migrate(db: &Database) -> Result<(), Error> {
  db.execute("CREATE TABLE IF NOT EXISTS schema_version (version INT)")?;

  let version: Int = db.query_one("SELECT MAX(version) FROM schema_version")?;

  if version < 1 {
    db.execute("CREATE TABLE users (...)")?;
    db.execute("INSERT INTO schema_version VALUES (1)")?;
  }
  if version < 2 {
    db.execute("ALTER TABLE users ADD COLUMN created_at TEXT")?;
    db.execute("INSERT INTO schema_version VALUES (2)")?;
  }
  Ok(())
}
```

